function notify(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(saveTimer);saveTimer=setTimeout(()=>$('toast').classList.remove('show'),2300)}
function snapshot(){return JSON.stringify({version:2,items,decorations})}function restore(s){let d=JSON.parse(s);items=d.items;decorations=d.decorations||[];selected=null;selectedDecor=null}function remember(){requireShared();history.push(snapshot());if(history.length>60)history.shift();future=[]}function save(){if(syncApplying)return;if(SHARED_ENABLED){sharedSync?.changed();return}try{localStorage.setItem('qiju-v2',snapshot());$('saved').textContent='● 离线文件 · 仅本机'}catch{$('saved').textContent='请导出方案备份'}}
function requireShared(){if(SHARED_ENABLED&&!sharedSync?.ready){notify('请等待共享布局连接完成');throw Error('Shared layout is not ready')}}

function changed(){save();renderPanel();draw();$('undo').disabled=!history.length;$('redo').disabled=!future.length}
function bounds(i){let p=getP(i),r=i.r%180!==0;return[i.x-(r?p.d:p.w)/2,i.y-(r?p.w:p.d)/2,i.x+(r?p.d:p.w)/2,i.y+(r?p.w:p.d)/2]}
function overlap(a,b){return a[0]<b[2]-5&&a[2]>b[0]+5&&a[1]<b[3]-5&&a[3]>b[1]+5}
function issue(i){const b=bounds(i);if(walls.some(w=>overlap(b,w.rect_mm)))return '与固定墙体重叠';for(let x=b[0]+5;x<=b[2];x+=Math.min(100,b[2]-b[0]-10))for(let y=b[1]+5;y<=b[3];y+=Math.min(100,b[3]-b[1]-10)){if(!floors.some(f=>x>=f.rect_mm[0]&&x<=f.rect_mm[2]&&y>=f.rect_mm[1]&&y<=f.rect_mm[3]))return '超出可布置地面'}if(getP(i).kind!=='rug'&&items.some(j=>j.id!==i.id&&getP(j).kind!=='rug'&&overlap(b,bounds(j))))return '与其他家具重叠';return ''}
function oldThumb(p){let c=p.color;return `<svg viewBox="0 0 120 90" aria-hidden="true"><ellipse cx="61" cy="76" rx="42" ry="7" fill="#dce0d4"/><path d="M24 40L65 22 104 41 63 61Z" fill="${c}"/><path d="M24 40L63 61 63 74 24 53Z" fill="${c}" style="filter:brightness(.86)"/><path d="M63 61L104 41 104 54 63 74Z" fill="${c}" style="filter:brightness(.72)"/>${p.kind==='sofa'||p.kind==='chair'?`<path d="M24 40L24 21 65 5 65 22Z" fill="${c}"/><path d="M65 5L104 25 104 41 65 22Z" fill="${c}" style="filter:brightness(.9)"/>`:p.kind==='lamp'?'<path d="M63 60V17" stroke="#5f645a" stroke-width="5"/><path d="M46 21L52 3 75 3 83 21Z" fill="#7d8276"/>':''}</svg>`}
function renderCatalog(){const cats=['全部',...new Set(products.map(p=>p.type))];$('categories').innerHTML=cats.map(c=>`<button class="${category===c?'active':''}">${c}</button>`).join('');$('categories').querySelectorAll('button').forEach(b=>b.onclick=()=>{category=b.textContent;renderCatalog()});let list=products.filter(p=>(category==='全部'||p.type===category)&&(p.name+p.type).toLowerCase().includes($('search').value.toLowerCase()));$('catalog').innerHTML=list.map(p=>`<button class="product" data-id="${p.id}" title="添加 ${p.name}"><div class="thumb">${p.image?'<img src="'+p.image+'" alt="'+p.name+' 三维预览">':oldThumb(p)}</div><span class="plus">＋</span><div class="info"><strong>${p.name}</strong><small>${p.type} · ${p.w/10} × ${p.d/10} cm</small><span class="price">${p.price?'¥ '+p.price.toLocaleString():'价格待核实'}</span></div></button>`).join('')||'<p>没有匹配的家具</p>';$('catalog').querySelectorAll('button').forEach(b=>b.onclick=()=>add(b.dataset.id))}
function add(pid){if(mode.startsWith('wall'))setMode('iso');remember();let p=products.find(p=>p.id===pid),[x,y]=rooms[focus];if(focus==='全屋'){x=2300;y=5000}let i={id:crypto.randomUUID(),pid,x,y,r:0,color:p.color};items.push(i);selected=i.id;changed();notify('已搬入 '+p.name+'，拖动试试吧')}
function renderPanel(){if(mode.startsWith('wall')){renderWallPanel();return}const i=current(),p=i&&getP(i);$('count').textContent=items.length;$('total').textContent='¥'+items.reduce((s,i)=>s+(getP(i).price||0),0).toLocaleString()+ (items.some(i=>getP(i).price===null)?' + 待询价':'');$('selection').innerHTML=!i?'<div class="empty-selection">⌁<br>选一件喜欢的家具<br><small>从左侧家具库开始布置</small></div>':`<small>IKEA · 宜家</small><h3 class="selected-title">${p.name}</h3><div class="selected-meta">${p.type} · ${p.w/10} × ${p.d/10} × ${p.h/10} cm<br>旋转 ${i.r}° · ${p.price?'参考价 ¥'+p.price:'价格待核实'}</div><div class="position-inputs"><label>X 坐标 / cm<input type="number" id="pos-x" value="${i.x/10}" step="10"></label><label>Y 坐标 / cm<input type="number" id="pos-y" value="${i.y/10}" step="10"></label></div><div class="selected-actions"><button id="rotate-item">旋转 ↻</button><button id="duplicate">复制</button><button id="delete">移除</button></div><label class="swatch-label"><input type="color" id="color" value="${i.color}"> 试配色（非商品可售颜色）</label><div class="status ${issue(i)?'bad':''}">${issue(i)?'⚠ '+issue(i):'✓ 未检测到墙体或家具重叠'}</div><p class="muted">未校验开门范围、运输及通行净宽。<br>${p.note}</p><a href="${p.url}" target="_blank" rel="noopener">查看宜家商品 / 系列 ↗</a>`;if(i){$('rotate-item').onclick=rotate;$('delete').onclick=remove;$('duplicate').onclick=()=>{remember();let j={...i,id:crypto.randomUUID(),x:i.x+400,y:i.y+400};items.push(j);selected=j.id;changed()};$('color').onchange=e=>{remember();i.color=e.target.value;changed()};for(const a of ['x','y'])$('pos-'+a).onchange=e=>{const v=Number(e.target.value);if(!Number.isFinite(v))return;remember();i[a]=Math.max(-1000,Math.min(14000,v*10));changed()}}}
function rotate(){if(!current())return;remember();current().r=(current().r+90)%360;changed()}function remove(){if(!current())return;remember();items=items.filter(i=>i.id!==selected);selected=null;changed()}
const canvas=$('scene');
let viewer;
function roomFaces(){return surfaces.filter(s=>surfaceRoom(s,focus))}
function draw(){if(!viewer)return;viewer.setState({items,products,selected,invalid:current()?!!issue(current()):false,room:focus,mode,fullWalls:$('full-walls').checked,surface:surfaces.find(s=>s.id===selectedSurface),surfaces,roomSurfaces:roomFaces(),decorations,selectedDecor})}
canvas.onkeydown=e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='r'||e.key==='R'){e.preventDefault();rotate()}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();if(mode==='wall')removeDecor();else remove()}if(e.key.startsWith('Arrow')){e.preventDefault();const step=e.shiftKey?100:10;if(mode==='wall'&&selectedDecor){remember();let d=decorations.find(d=>d.id===selectedDecor),face=surfaces.find(s=>s.id===d.surface);if(e.key==='ArrowLeft')d.u-=step;if(e.key==='ArrowRight')d.u+=step;if(e.key==='ArrowUp')d.v+=step;if(e.key==='ArrowDown')d.v-=step;Object.assign(d,fitDecoration(d,face));changed()}else if(current()){remember();let i=current();if(e.key==='ArrowLeft')i.x-=step;if(e.key==='ArrowRight')i.x+=step;if(e.key==='ArrowUp')i.y-=step;if(e.key==='ArrowDown')i.y+=step;changed()}}};
$('undo').onclick=()=>{if(!history.length)return;future.push(snapshot());restore(history.pop());changed()};$('redo').onclick=()=>{if(!future.length)return;history.push(snapshot());restore(future.pop());changed()};
$('search').oninput=renderCatalog;$('iso').onclick=()=>setMode('iso');$('plan').onclick=()=>setMode('plan');$('wall-mode').onclick=()=>{if(focus==='全屋')enterRoom('客餐厅');selectedSurface=null;selectedDecor=null;selected=null;setMode('wall-pick');notify('鼠标扫过墙面查看高亮，点击进入正面设计')};
function setMode(m){mode=m;document.querySelector('.workspace').classList.toggle('wall-design',m.startsWith('wall'));viewer?.setRoom();for(let k of ['iso','plan','wall-mode'])$(k).classList.toggle('active',k===(m.startsWith('wall')?'wall-mode':m));$('wall-controls').hidden=!m.startsWith('wall');$('wall-guide').hidden=!m.startsWith('wall');$('wall-back').hidden=m!=='wall';$('scene').setAttribute('aria-label',m==='wall'?'墙面编辑：保留墙前家具，拖动装饰、方向键微调':m==='wall-pick'?'选墙模式：鼠标悬停墙面高亮，点击进入正面视角':'三维房间：拖动家具移动，拖动空白旋转视角');updateWallControls();renderPanel();draw()}
$('rotate-view').onclick=()=>{viewer.yaw+=Math.PI/2;viewer.archKey='';draw()};$('zoom-in').onclick=()=>{viewer.zoom=Math.min(3.5,viewer.zoom*1.15);viewer.render()};$('zoom-out').onclick=()=>{viewer.zoom=Math.max(.5,viewer.zoom/1.15);viewer.render()};$('reset-view').onclick=()=>{viewer.setRoom();draw()};$('full-walls').onchange=draw;
function enterRoom(r){focus=r;selected=null;selectedDecor=null;selectedSurface=null;viewer?.setRoom();$('room-title').textContent=focus==='全屋'?'全屋漫游':focus+' · 独立设计';$('room-subtitle').textContent=focus==='全屋'?'进入房间，设计每一个角落':'墙高 236 cm · 拖动空白旋转 · 前墙自动剖开';if(mode.startsWith('wall')){mode='wall-pick';selectedSurface=null;updateWallControls()}roomButtons();changed()}
function roomButtons(){$('rooms').innerHTML=Object.keys(rooms).map(r=>`<button class="${focus===r?'active':''}">${r==='全屋'?'⌂ 全屋':r}</button>`).join('');$('rooms').querySelectorAll('button').forEach(b=>b.onclick=()=>enterRoom(b.textContent.replace('⌂ ','')))}
function starter(){remember();items=items.filter(i=>!['kivik','lack','lisabo','chair','lo hals'].includes(i.pid));for(const [pid,x,y,r] of [['kivik',4200,5700,270],['lack',2500,5700,90],['lo hals',2550,5700,0],['lisabo',1550,2250,90],['chair',900,1950,270],['chair',900,2600,270],['chair',2200,1950,90],['chair',2200,2600,90]])items.push({id:crypto.randomUUID(),pid,x,y,r,color:products.find(p=>p.id===pid).color});selected=null;changed();notify('客厅灵感方案已就位，可以继续自由调整')}
$('starter').onclick=starter;
function modal(content){$('modal-content').innerHTML=content;$('modal').showModal()}$('close').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close()};
function photos(){modal('<div class="eyebrow">THE ORIGINAL HOME</div><h2>家的原本模样</h2><p>根据 real_pic 中的实景照片匹配硬装色彩。照片用于参考，未进行照片级三维重建。</p><div class="photo-grid"><img src="assets/room-0.jpeg" alt="现有精装实景一"><img src="assets/room-1.jpeg" alt="现有精装实景二"></div><p>灰色亮面砖、白色墙面及黑色门框保留。其他房间材质尚未通过照片确认。</p>')}$('photos').onclick=photos;$('reference').onclick=photos;
$('shopping').onclick=()=>{const counts={};items.forEach(i=>counts[i.pid]=(counts[i.pid]||0)+1);modal('<div class="eyebrow">FROM YOUR ROOM TO REAL LIFE</div><h2>我的采购清单</h2><p>官网信息核对日期：2026-10-12。参考价格可能随配置变化；未核实南宁库存、配送与安装费用。</p>'+Object.entries(counts).map(([id,n])=>{const p=products.find(p=>p.id===id);return `<div class="shopping-row"><div><strong>${p.name} × ${n}</strong><small>${p.w/10} × ${p.d/10} × ${p.h/10} cm · ${p.note}</small></div><span>${p.price?'¥'+p.price*n:'待询价'}</span><a href="${p.url}" target="_blank" rel="noopener">官网 ↗</a></div>`}).join('')+(!items.length?'<p>还没有家具，先从家具库搬几件回家吧。</p>':'')+'<p>模型的配色和外观仅用于搭配预览，请以具体商品详情为准。</p><button id="download-list">导出采购清单 CSV</button>');$('download-list').onclick=()=>download('采购清单.csv','\ufeff名称,数量,宽cm,深cm,高cm,单价,官网\n'+Object.entries(counts).map(([id,n])=>{let p=products.find(p=>p.id===id);return [p.name,n,p.w/10,p.d/10,p.h/10,p.price??'待询价',p.url].join(',')}).join('\n'),'text/csv')};
function download(name,text,type){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('export').onclick=()=>download('栖居-软装方案.json',JSON.stringify({version:2,items,decorations},null,2),'application/json');$('import-btn').onclick=()=>$('import').click();
function validate(list,preserveIds=false){if(!Array.isArray(list)||list.length>300)throw Error();return list.map(i=>{if(!products.some(p=>p.id===i.pid)||![i.x,i.y,i.r].every(Number.isFinite)||Math.abs(i.x)>20000||Math.abs(i.y)>20000||![0,90,180,270].includes(i.r)||!/^#[0-9a-f]{6}$/i.test(i.color))throw Error();if(preserveIds&&!/^[a-zA-Z0-9_-]{1,100}$/.test(i.id))throw Error();return{id:preserveIds?i.id:crypto.randomUUID(),pid:i.pid,x:i.x,y:i.y,r:i.r,color:i.color}})}
function validDecor(list,preserveIds=false){if(!Array.isArray(list)||list.length>150)throw Error();return list.map(d=>{const face=surfaces.find(f=>f.id===d.surface);if(!face||!['art','mirror','shelf','lamp'].includes(d.kind)||![d.u,d.v,d.w,d.h].every(Number.isFinite)||d.w<50||d.h<50||d.w>face.length||d.h>WALL_HEIGHT)throw Error();if(preserveIds&&!/^[a-zA-Z0-9_-]{1,100}$/.test(d.id))throw Error();return fitDecoration({id:preserveIds?d.id:crypto.randomUUID(),surface:d.surface,kind:d.kind,u:d.u,v:d.v,w:d.w,h:d.h},face)})}
$('import').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(![1,2].includes(data.version))throw Error();let next=validate(data.items),decs=validDecor(data.decorations||[]);remember();items=next;decorations=decs;selected=null;selectedDecor=null;changed();notify('方案导入成功（含墙面装饰）')}catch{notify('无法导入：请选择有效的栖居方案 JSON')}e.target.value=''};
const faceNames={north:'北向面',south:'南向面',east:'东向面',west:'西向面'};
const wallNames={kitchen_south_W12:'厨房外侧墙',kitchen_left_upper:'厨房入口侧墙',kitchen_left_lower:'厨房入口短墙',entry_W40:'入户门左墙',entry_W02:'入户门右墙',between_doors_W13:'走廊门间墙',south_W36:'阳台入口左墙',south_W34:'阳台入口右墙',south_W23:'卧一飘窗左墙',south_W20:'卧一飘窗右墙',tv_W38:'电视背景墙',west_upper:'客餐厅西墙',kitchen_right:'厨房 / 客卫隔墙',right_bath_south_W18:'主卫 / 卧一交界墙',bed2_south_W17:'卧二南墙',bed3_west_W26_W33:'卧三西墙',master_west_W24:'卧一西墙',east_outer:'东侧外墙'};
const decorNames={art:'装饰画',mirror:'圆镜',shelf:'壁挂置物架',lamp:'壁灯'};
function faceName(f){return (wallNames[f.wall]||f.wall)+' · '+faceNames[f.side]+' · '+Math.round(f.length/10)+' cm'}
function updateWallControls(){const list=roomFaces();if(mode==='wall'&&!list.some(f=>f.id===selectedSurface))selectedSurface=list[0]?.id;$('wall-select').innerHTML='<option value="">在房间内悬停并点击墙面…</option>'+list.map(f=>`<option value="${f.id}">${faceName(f)}</option>`).join('');$('wall-select').value=selectedSurface||'';let f=surfaces.find(f=>f.id===selectedSurface);$('wall-guide').textContent=f?`← ${Math.round(f.length/10)} cm →　｜　墙高 236 cm　｜　拖动画面中的装饰调整位置`:'鼠标扫过墙面高亮 · 点击拉近至正面 · 拖空白可旋转房间'}
$('wall-select').onchange=e=>{if(!e.target.value)return;selectedSurface=e.target.value;selectedDecor=null;setMode('wall')};
$('wall-back').onclick=()=>{selectedSurface=null;selectedDecor=null;setMode('wall-pick')};
for(const b of document.querySelectorAll('[data-decor]'))b.onclick=()=>{let f=surfaces.find(f=>f.id===selectedSurface);if(!f){notify('先点击房间中的一面墙');return}let kind=b.dataset.decor,w=kind==='shelf'?800:kind==='lamp'?200:600,h=kind==='art'?800:kind==='mirror'?600:kind==='shelf'?250:200;w=Math.min(w,f.length-20);if(w<100){notify('这段墙面太窄');return}remember();let d={id:crypto.randomUUID(),surface:f.id,kind,w,h,u:f.length/2,v:1500};const used=decorations.filter(x=>x.surface===f.id);let placed=false;for(let v of [1500,900,1900]){for(let u= w/2+100;u<=f.length-w/2-50;u+=100){if(!used.some(x=>Math.abs(x.u-u)<(x.w+w)/2+80&&Math.abs(x.v-v)<(x.h+h)/2+80)){d.u=u;d.v=v;placed=true;break}}if(placed)break}decorations.push(fitDecoration(d,f));selectedDecor=d.id;changed();notify('已添加'+decorNames[kind])};
function removeDecor(){if(!selectedDecor)return;remember();decorations=decorations.filter(d=>d.id!==selectedDecor);selectedDecor=null;changed()}
function renderWallPanel(){const face=surfaces.find(f=>f.id===selectedSurface),d=decorations.find(d=>d.id===selectedDecor);$('selection').innerHTML=face?`<small>WALL ATELIER · 墙面工作室</small><h3 class="selected-title">${wallNames[face.wall]||'选中墙段'}</h3><p>净长 ${Math.round(face.length/10)} cm × 高 236 cm<br>保留墙前家具，结合实际摆放设计装饰。</p>${d?`<h3>${decorNames[d.kind]}</h3><div class="decor-fields"><label>距左侧中心 / cm<input id="decor-u" type="number" step="1" value="${d.u/10}"></label><label>离地中心 / cm<input id="decor-v" type="number" step="1" value="${d.v/10}"></label><label>宽度 / cm<input id="decor-w" type="number" min="5" value="${d.w/10}"></label><label>高度 / cm<input id="decor-h" type="number" min="5" value="${d.h/10}" ${d.kind==='mirror'?'disabled':''}></label></div><button id="decor-remove">移除装饰</button><p>装饰底边距地 ${Math.round((d.v-d.h/2)/10)} cm</p>`:'<div class="empty-selection">选择上方装饰类型<br>或点击墙面上的装饰</div>'}<small>装饰是可调尺寸设计占位，不计入真实家具采购金额。圆镜为金属质感示意，不做实时镜面反射。</small>`:'<div class="empty-selection">在房间内选择一面墙<br><small>鼠标扫过时高亮，点击后拉近正对墙面。墙前家具会保留，方便一起看搭配。</small></div>';if(d){$('decor-remove').onclick=removeDecor;for(let k of ['u','v','w','h'])$('decor-'+k).onchange=e=>{let value=Number(e.target.value)*10;if(!Number.isFinite(value))return;remember();d[k]=value;d.w=Math.max(50,Math.min(face.length,d.w));d.h=Math.max(50,Math.min(WALL_HEIGHT,d.h));if(d.kind==='mirror'){d.w=Math.min(d.w,WALL_HEIGHT);d.h=d.w}Object.assign(d,fitDecoration(d,face));changed()}}}
$('junction-kitchen').onclick=()=>{enterRoom('客卫');selectedSurface=surfaces.find(f=>f.wall==='kitchen_right'&&f.side==='east')?.id;setMode('wall');notify('厨房 / 客卫隔墙：已合并交接表面')};$('junction-master').onclick=()=>{enterRoom('卧1');selectedSurface=surfaces.find(f=>f.wall==='right_bath_south_W18'&&f.side==='south')?.id;setMode('wall');notify('主卫 / 卧一交界：已合并交接表面')};
try{viewer=new Viewer(canvas,D,{select:id=>{selected=id;changed()},selectDecor:id=>{selectedDecor=id;changed()},begin:remember,move:(id,x,y)=>{let i=items.find(i=>i.id===id),step=$('snap').checked?100:10;i.x=Math.max(-1000,Math.min(14000,Math.round(x/step)*step));i.y=Math.max(-1000,Math.min(12000,Math.round(y/step)*step));draw()},moveDecor:(id,u,v)=>{let d=decorations.find(d=>d.id===id),step=$('snap').checked?100:10;Object.assign(d,fitDecoration({...d,u:Math.round(u/step)*step,v:Math.round(v/step)*step},surfaces.find(s=>s.id===d.surface)));draw()},commit:changed,selectWall:(wall,side,surfaceId)=>{let f=roomFaces().find(f=>surfaceId?f.id===surfaceId:f.wall===wall&&f.side===side);if(f){selectedSurface=f.id;setMode('wall')}}});for(const p of products)p.image=viewer.thumbnail(p)}catch(e){$('render-error').hidden=false;$('render-error').textContent='三维渲染未能启动，请使用支持 WebGL 2 的浏览器。错误：'+e.message;console.error(e)}

function syncStatus(text,revision){$('saved').textContent=text;$('shared-status').textContent=text+(revision?' · 版本 '+revision:'');document.body.classList.toggle('sync-loading',SHARED_ENABLED&&!sharedSync?.ready)}
function applyShared(layout,external){const next=validate(layout.items,true),decs=validDecor(layout.decorations||[],true);syncApplying=true;items=next;decorations=decs;if(!items.some(i=>i.id===selected))selected=null;if(!decorations.some(d=>d.id===selectedDecor))selectedDecor=null;if(external){history=[];future=[]}changed();syncApplying=false;}
function preserveConflict(layout,count){try{localStorage.setItem('qiju-conflict-draft',JSON.stringify(layout))}catch{}$('conflict-download').hidden=false;notify(count+' 项被其他人修改，已保留你的冲突草稿，可导出后重新调整')}
$('conflict-download').onclick=()=>download('共享冲突草稿.json',localStorage.getItem('qiju-conflict-draft')||snapshot(),'application/json');
$('reconnect').onclick=()=>sharedSync?.tick();
$('local-backup').onclick=()=>{const old=localStorage.getItem('qiju-v2');if(old)download('原本机布局备份.json',old,'application/json');else notify('本浏览器没有旧版本机布局')};
if(SHARED_ENABLED){
 document.body.classList.add('sync-loading');
 sharedSync=new SharedSync({url:SHARED_API,fetcher:supabaseTransport(SHARED_API,'sb_publishable_2PTVZ2l7J8eGocDgZr1wpw_cr6nJK3a'),read:()=>JSON.parse(snapshot()),apply:applyShared,status:syncStatus,conflict:preserveConflict,busy:()=>!!viewer?.drag||!!document.querySelector('.position-inputs input:focus,.decor-fields input:focus')});
 sharedSync.start();
 window.addEventListener('online',()=>sharedSync.tick());document.addEventListener('visibilitychange',()=>{if(!document.hidden)sharedSync.tick()});
 window.addEventListener('beforeunload',e=>{if(sharedSync.ready&&!equal(sharedSync.base,JSON.parse(snapshot()))){e.preventDefault();e.returnValue='还有尚未同步的修改'}});
}else{document.querySelector('.shared-banner strong').textContent='离线设计 · 本机保存';$('reconnect').hidden=true;try{const saved=localStorage.getItem('qiju-v2'),old=localStorage.getItem('qiju-v1');if(saved){const data=JSON.parse(saved);items=validate(data.items);decorations=validDecor(data.decorations||[])}else if(old)items=validate(JSON.parse(old));else starter()}catch{notify('旧方案无法读取，请导入备份')}syncStatus('离线文件 · 布局仅保存在本机',0)}
renderCatalog();roomButtons();changed();
